ALTER TABLE "wb_next"."generation_jobs" DROP CONSTRAINT "generation_input";--> statement-breakpoint
ALTER TABLE "wb_next"."generation_jobs" ADD COLUMN "native_quote_version" text;--> statement-breakpoint
ALTER TABLE "wb_next"."generation_jobs" ADD CONSTRAINT "generation_input" CHECK (length(btrim("wb_next"."generation_jobs"."prompt")) between 1 and 3000 and length("wb_next"."generation_jobs"."prompt") <= 3000 and "wb_next"."generation_jobs"."resolution" in ('480p', '720p') and "wb_next"."generation_jobs"."aspect_ratio" in ('9:16', '16:9', '1:1') and (("wb_next"."generation_jobs"."duration_sec" = 5 and "wb_next"."generation_jobs"."native_quote_version" is null) or ("wb_next"."generation_jobs"."duration_sec" = 10 and "wb_next"."generation_jobs"."resolution" = '720p' and "wb_next"."generation_jobs"."aspect_ratio" = '9:16' and "wb_next"."generation_jobs"."category" is not null and "wb_next"."generation_jobs"."native_quote_version" is not null and "wb_next"."generation_jobs"."native_quote_version" ~ '^[a-f0-9]{64}$' and "wb_next"."generation_jobs"."model" in ('mock-native:text', 'mock-native:reference'))));